    if (error.name === 'ResourceNotFoundException') {
      console.warn('⚠️ Bedrock 모델 접근 불가 - 유사도 기반 결과만 반환');
      return { explanation: null, fallbackMode: true };
    }
    throw error;
  }
}
```

