  limit(() => vectorSearchWithRetry(q))
);
```

### 3️⃣ **중기 개선 - 캐싱 추가**
```javascript
const NodeCache = require('node-cache');
const cache = new NodeCache({ stdTTL: 3600 }); // 1시간 캐시

async function cachedVectorSearch(query) {
  const cached = cache.get(query);
  if (cached) return cached;

  const result = await vectorSearchWithRetry(query);
  cache.set(query, result);
  return result;
}
```

